import{renderCustomModel,renderDiagram}from './visual.js?v=20261023-physicscomplete01';import{sensesFigure}from './senses-figures.js?v=20261023-physicscomplete01';
import{buildSenses}from './senses-meshes.js?v=20261023-physicscomplete01';
export function showSenses(spec='eye',w={}){let[k,s]=spec.split(':'),kind=k,state=s==='1'&&k==='accommodation'?'near':s==='2'&&k==='eye'?'dim':k==='vision'?'myopia':s||'far',o={kind,state,corrected:k==='vision'&&s==='1',...w},title=w.title||({brain:'Brain regions',eye:'Inside the eye',pupil:'Controlling light entry',accommodation:'Changing lens shape',vision:'Focus and correction',evidence:'Compare the evidence'})[kind],figure=sensesFigure(o);if(['evidence','pupil','accommodation','vision'].includes(kind)||o.concealed){renderDiagram(title,w.label||'Predict, compare and explain',figure,'SCHEMATIC EVIDENCE');return;}renderCustomModel({name:title,formula:w.label||'Use the labelled diagram to locate structures',kicker:'ANATOMICAL CUTAWAY',aria:title+'; schematic cutaway with paired labelled diagram.',atoms:[],bonds:[],radius:2.0,viewKey:'senses-'+kind,startPaused:true,note:'Simplified shape and enlarged structures · not a clinical image',diagram:figure,build:(g,T)=>buildSenses(g,T,o)});}
